    let mc = 0.5 * ab - ap; let md = dot(mc, r); let hl = 0.5 * length(ab) + A.w + 0.05;   // the tube's bounding sphere: off the ray, skip
    if (md < -hl || dot(mc, mc) - md * md > hl * hl) { continue; }
