    let bb = dot(r, ab); let cc = max(dot(ab, ab), 1e-8); let d = dot(r, ap); let e = dot(ab, ap);
    let den = cc - bb * bb;
    var u = select(e / cc, (e - bb * d) / den, den > 1e-6 * cc); u = clamp(u, 0.0, 1.0);
    let q = A.xyz + u * ab; let t = dot(q - p, r);
