    let o = (p - oc) / oa; let dd = dv / oa; let s = clamp(-dot(o, dd) / max(dot(dd, dd), 1e-6), 0.0, 1.0);
    e0 += w; e1 += w * smoothstep(0.5, 1.35, length(o + dd * s));
