    let tw = 1.0 - abs(o) / (0.5 * len + 1e-4); let wk = 0.04 + tw * tw;   // (a tent, squared: the streak brightest at the bulb's own place, tapering off)
    if (uv.y < 0.0 || uv.y > 1.0) { s += hiK(c0) * wk; w += wk; continue; }
