  let pw = smoothstep(0.2, 0.55, hgt * 0.7 + 0.45 * sfNf(vec2f(u * 1.1, v * 3.0) + rid * 20.0, max(fw.x * 1.1, fw.y * 3.0)) - 0.35 * tp + 0.12);
